/** Additive, immutable V2 launch and actual-start witnesses. A queue is never a
 * protocol selector. Historical reads grant no execution permission. */
public final class TaskRunWorkflowProtocolBinding {
    static final String BIND="task.run.protocol.v2", ACCEPT="task.run.protocol.accepted.v2";
    static final String MANIFEST=manifest();
    private final JdbcTemplate db;private final PermissionSchema json;private final TaskRunBootstrapSchema schema;
    private final TaskRunSectionWriterProtocolBinding writers;
    private final TaskRunSourceVerifierProtocolBinding verifiers;
    private final TaskRunCandidateAssemblyProtocolBinding assemblies;
    TaskRunCandidateAssemblyProtocolBinding assemblies(){return assemblies;}
    TaskRunSourceVerifierProtocolBinding verifiers(){return verifiers;}
    TaskRunSectionWriterProtocolBinding writers(){return writers;}
    private final TaskRunWorkflowLedger launches;private final TaskRunActivityJournal journal;
    public TaskRunWorkflowProtocolBinding(DataSource data,PermissionSchema json,TaskRunBootstrapSchema schema,TaskRunWorkflowLedger launches){this(new JdbcTemplate(data),json,schema,launches);}
    TaskRunWorkflowProtocolBinding(JdbcTemplate db,PermissionSchema json,TaskRunBootstrapSchema schema,TaskRunWorkflowLedger launches){this.db=Objects.requireNonNull(db);this.json=Objects.requireNonNull(json);this.schema=Objects.requireNonNull(schema);this.launches=Objects.requireNonNull(launches);this.journal=new TaskRunActivityJournal(db,json);this.writers=new TaskRunSectionWriterProtocolBinding(db,json,schema,this);this.verifiers=new TaskRunSourceVerifierProtocolBinding(db,json,schema,this);this.assemblies=new TaskRunCandidateAssemblyProtocolBinding(db,json,schema,this);db.setQueryTimeout(5);}

    Bound prepare(TaskRunBootstrapAuthority.Verified p,TaskRunWorkflowLedger.Intent intent,WaitingWorkflowDeploymentV2 deployment)throws Exception{
        p.requireUnchanged();var a=p.admission();var row=run(a,p.runId());same(p.projectId(),text(row,"project_id"));same("QUEUED",text(row,"status"));if(row.get("started_at")!=null)bad();
        same(p.command().required("command").required("command_id").asText(),intent.commandId());same(p.runId(),intent.reference().runId());deployment.require(intent.reference(),intent.namespace());
        var value=binding(intent.content(),deployment);var existing=readBinding(a,row,intent.content());
        if(existing.isPresent()){same(json.canonical(value),json.canonical(existing.get()));p.requireUnchanged();return new Bound(intent,value,deployment);}
        // A prior V1 attempt cannot be retrospectively relabelled as V2.
        if(!db.queryForList("SELECT launch_id FROM task_run_workflow_attempt WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId()).isEmpty()||!db.queryForList("SELECT launch_id FROM task_run_workflow_acceptance WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",p.tenantId(),p.runId()).isEmpty())bad();
        p.requireUnchanged();journal.write(a,p.projectId(),p.runId(),id(intent.launchId(),false),BIND,key(p.runId(),false),intent.commandId(),schema.hash(intent.content()),p.classification(),"2.0.0",MANIFEST,value);
        same(json.canonical(value),json.canonical(readBinding(a,row,intent.content()).orElseThrow()));return new Bound(intent,value,deployment);
    }
    Bound prepare(TaskRunBootstrapAuthority.Verified p,TaskRunWorkflowLedger.Intent intent,WaitingWorkflowDeploymentV2 deployment,com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 extension)throws Exception{var b=prepare(p,intent,deployment);if(extension!=null)writers.prepare(p,intent,deployment,extension);else if(writers.original(p.admission(),intent,deployment)!=null)bad();return bound(p.admission(),run(p.admission(),p.runId()),intent);}
    Bound prepare(TaskRunBootstrapAuthority.Verified p,TaskRunWorkflowLedger.Intent intent,WaitingWorkflowDeploymentV2 deployment,com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 writer,com.ruoyi.medical.workflow.SourceVerifierWorkflowExtensionV1 verifier)throws Exception{prepare(p,intent,deployment,writer);if(verifier!=null){if(writer==null)bad();verifiers.prepare(p,intent,deployment,writer,verifier);}else if(verifiers.original(p.admission(),intent,deployment,writer)!=null)bad();return bound(p.admission(),run(p.admission(),p.runId()),intent);}
    Bound prepare(TaskRunBootstrapAuthority.Verified p,TaskRunWorkflowLedger.Intent intent,WaitingWorkflowDeploymentV2 deployment,com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 writer,com.ruoyi.medical.workflow.SourceVerifierWorkflowExtensionV1 verifier,com.ruoyi.medical.workflow.CandidateAssemblyWorkflowExtensionV1 assembly)throws Exception{prepare(p,intent,deployment,writer,verifier);if(assembly!=null){if(verifier==null)bad();assemblies.prepare(p,intent,deployment,verifier,assembly);}else if(assemblies.original(p.admission(),intent,deployment,verifier)!=null)bad();return bound(p.admission(),run(p.admission(),p.runId()),intent);}
    StartPermit authorizeStart(TaskRunBootstrapAuthority.Verified p,TaskRunWorkflowLedger.Attempt attempt,TaskRunWorkflowConfiguration configuration,WaitingWorkflowDeploymentV2 deployment)throws Exception{
        p.requireUnchanged();var b=bound(p.admission(),run(p.admission(),p.runId()),attempt.intent());same(deployment,b.deployment);var permit=launches.authorizeStart(p,attempt,configuration);p.requireUnchanged();return new StartPermit(permit,b);
    }
    RecoveryPermit authorizeRecovery(EnterpriseAccess.Admission a,TaskRunLaunchRecoveryAuthority.Verified p)throws Exception{
        p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());var permit=launches.authorizeRecovery(p);var b=bound(a,run(a,p.runId()),permit.intent());p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());return new RecoveryPermit(permit,b);
    }
    TaskRunWorkflowLedger.Receipt record(EnterpriseAccess.Admission a,TaskRunLaunchRecoveryAuthority.Verified p,TaskRunWorkflowDeliveryV2.Received received)throws Exception{
        p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());var intent=launches.recover(p);var b=bound(a,run(a,p.runId()),intent);same(b.value,received.binding().value);same(b.deployment.canonicalSha256(),received.protocolSha256());
        // The bridge accepts only a private Received from actual V2 SDK start/query.
        var receipt=launches.record(p,TaskRunWorkflowDelivery.fromV2(received));var value=acceptance(b,receipt);
        var existing=readAcceptance(a,run(a,p.runId()),b,receipt);
        if(existing.isEmpty())journal.write(a,p.projectId(),p.runId(),id(intent.launchId(),true),ACCEPT,key(p.runId(),true),intent.commandId(),schema.hash(value.required("binding")),p.classification(),"2.0.0",MANIFEST,value);
        else same(json.canonical(value),json.canonical(existing.get()));
        requireWaitingV2(a,p.runId()).requireUnchanged();writers.record(a,received,receipt);verifiers.record(a,received,receipt);assemblies.record(a,received,receipt);p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());return receipt;
    }
    Optional<TaskRunWorkflowLedger.Receipt> read(EnterpriseAccess.Admission a,TaskRunLaunchRecoveryAuthority.Verified p)throws Exception{
        p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());var intent=launches.recover(p);var b=bound(a,run(a,p.runId()),intent);var receipt=launches.read(p);
        if(receipt.isEmpty()){if(!db.queryForList("SELECT operation_id FROM operation_record WHERE tenant_id=? AND operation_id=? LIMIT 2 FOR UPDATE",p.tenantId(),id(intent.launchId(),true)).isEmpty())bad();return Optional.empty();}
        // A legacy acceptance without actual V2 evidence is unresolved, not permission to start.
        if(readAcceptance(a,run(a,p.runId()),b,receipt.get()).isEmpty())return Optional.empty();if(b.extension()!=null){try{writers.requireAccepted(a,p.runId()).requireUnchanged();}catch(java.util.NoSuchElementException absent){return Optional.empty();}}if(b.verifier()!=null){try{verifiers.requireAccepted(a,p.runId()).requireUnchanged();}catch(java.util.NoSuchElementException absent){return Optional.empty();}}if(b.assembly()!=null){try{assemblies.requireAccepted(a,p.runId()).requireUnchanged();}catch(java.util.NoSuchElementException absent){return Optional.empty();}}p.requireUnchanged();same(p.tenantId(),a.context().tenant_id());same(p.actorId(),a.actorId());return receipt;
    }

    /** Factual receipt reader for AT08. Caller still needs its own current node/tool
     * authority. This method never mints that authority or contacts Temporal. */
    Accepted requireWaitingV2(EnterpriseAccess.Admission a,String runId)throws Exception{
        var snapshot=accepted(a,runId,a.actorId());return new Accepted(a,runId,snapshot,null);
    }
    Accepted requireQuestionOriginal(TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion q,String runId)throws Exception{
        q.requireUnchanged();same(q.runId(),runId);same(q.tenantId(),q.admission().context().tenant_id());
        var value=accepted(q.admission(),runId,q.originalActorId());q.requireUnchanged();return new Accepted(q.admission(),runId,value,q);
    }
    Accepted requireAssemblyOriginal(TaskCandidateAssemblyHumanReadAuthority.Verified human)throws Exception{human.require(human.admission());var value=accepted(human.admission(),human.runId(),human.originalActorId());return new Accepted(human.admission(),human.runId(),value,null,human);}
    private JsonNode accepted(EnterpriseAccess.Admission a,String runId,String actor)throws Exception{
        var row=runOriginal(a,runId,actor);String tenant=a.context().tenant_id(),project=text(row,"project_id"),classification=text(row,"classification");
        var launchRow=one(db.queryForList("SELECT * FROM task_run_workflow_launch WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",tenant,project,runId));metadata(launchRow,a,row,actor);
        var launch=schema.read(text(launchRow,"intent_json"));same(schema.hash(launch),text(launchRow,"intent_sha256"));same(schema.hash(launch.required("reference")),text(launchRow,"reference_sha256"));same(json.canonical(launch.required("reference")),json.canonical(schema.read(text(launchRow,"reference_json"))));
        for(String f:List.of("launch_id","command_id","command_sha256","workflow_id"))same(text(launchRow,f),launch.required(f).asText());
        var registration=one(db.queryForList("SELECT * FROM task_run_replay_registration WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",tenant,project,runId));metadata(registration,a,row,actor);var registered=schema.read(text(registration,"receipt_json"));same(schema.hash(registered),text(registration,"receipt_sha256"));schema.requireLaunch(registered,launch);
        for(var pin:Map.of("tenant_id",tenant,"project_id",project,"run_id",runId,"task_id",text(row,"task_id"),"initiator_id",actor).entrySet())same(pin.getValue(),launch.required(pin.getKey()).asText());same(text(row,"workflow_id"),launch.required("workflow_id").asText());
        var attempt=one(db.queryForList("SELECT * FROM task_run_workflow_attempt WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",tenant,project,runId));metadata(attempt,a,row,actor);same(text(launchRow,"launch_id"),text(attempt,"launch_id"));if(time(attempt,"created_at").isBefore(time(launchRow,"created_at")))bad();
        var binding=readBindingOriginal(a,actor,row,launch).orElseThrow(()->new TenantAccessException(ErrorCode.ACCESS_DENIED));var deployment=WaitingWorkflowDeploymentV2.load(binding.required("deployment_canonical").asText());same(json.canonical(binding(launch,deployment)),json.canonical(binding));
        var acceptanceRow=one(db.queryForList("SELECT * FROM task_run_workflow_acceptance WHERE tenant_id=? AND project_id=? AND run_id=? LIMIT 2 FOR UPDATE",tenant,project,runId));metadata(acceptanceRow,a,row,actor);var receipt=schema.read(text(acceptanceRow,"receipt_json"));schema.requireAcceptance(launch,receipt);same(schema.hash(receipt),text(acceptanceRow,"receipt_sha256"));same(text(launchRow,"launch_id"),text(acceptanceRow,"launch_id"));same(text(acceptanceRow,"temporal_run_id"),receipt.required("temporal_run_id").asText());
        var expected=acceptance(binding,receipt,text(acceptanceRow,"receipt_sha256"));String launchId=launch.required("launch_id").asText(),command=launch.required("command_id").asText();
        var result=journal.readOriginalActor(a,actor,project,runId,id(launchId,true),ACCEPT,key(runId,true),command,schema.hash(binding),classification,"2.0.0",MANIFEST).orElseThrow(()->new TenantAccessException(ErrorCode.ACCESS_DENIED));same(json.canonical(expected),json.canonical(result));return result;
    }
    private void metadata(Map<String,Object> value,EnterpriseAccess.Admission a,Map<String,Object> row,String actor){for(var pin:Map.of("tenant_id",a.context().tenant_id(),"project_id",text(row,"project_id"),"run_id",text(row,"run_id"),"created_by",actor,"classification",text(row,"classification"),"schema_version","1.0.0","schema_manifest_sha256",schema.manifest()).entrySet())same(pin.getValue(),value.get(pin.getKey()));}
    private Bound bound(EnterpriseAccess.Admission a,Map<String,Object> row,TaskRunWorkflowLedger.Intent intent)throws Exception{var value=readBinding(a,row,intent.content()).orElseThrow(()->new TenantAccessException(ErrorCode.ACCESS_DENIED));var deployment=WaitingWorkflowDeploymentV2.load(value.required("deployment_canonical").asText());same(json.canonical(binding(intent.content(),deployment)),json.canonical(value));var writer=writers.original(a,intent,deployment);var verifier=verifiers.original(a,intent,deployment,writer);return new Bound(intent,value,deployment,writer,verifier,assemblies.original(a,intent,deployment,verifier));}
    private Optional<JsonNode> readBinding(EnterpriseAccess.Admission a,Map<String,Object> row,JsonNode intent)throws Exception{return readBindingOriginal(a,a.actorId(),row,intent);}
    private Optional<JsonNode> readBindingOriginal(EnterpriseAccess.Admission a,String actor,Map<String,Object> row,JsonNode intent)throws Exception{return journal.readOriginalActor(a,actor,text(row,"project_id"),text(row,"run_id"),id(intent.required("launch_id").asText(),false),BIND,key(text(row,"run_id"),false),intent.required("command_id").asText(),schema.hash(intent),text(row,"classification"),"2.0.0",MANIFEST);}
    private Optional<JsonNode> readAcceptance(EnterpriseAccess.Admission a,Map<String,Object> row,Bound b,TaskRunWorkflowLedger.Receipt receipt)throws Exception{var found=journal.read(a,text(row,"project_id"),text(row,"run_id"),id(b.intent.launchId(),true),ACCEPT,key(text(row,"run_id"),true),b.intent.commandId(),schema.hash(b.value),text(row,"classification"),"2.0.0",MANIFEST);if(found.isPresent())same(json.canonical(acceptance(b,receipt)),json.canonical(found.get()));return found;}
    private JsonNode binding(JsonNode intent,WaitingWorkflowDeploymentV2 deployment)throws Exception{var reference=com.fasterxml.jackson.databind.json.JsonMapper.builder().propertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE).build().treeToValue(intent.required("reference"),com.ruoyi.medical.workflow.WorkflowProtocol.Reference.class);deployment.require(reference,intent.required("temporal_namespace").asText());var n=json.object().put("schema_version","2.0.0").put("kind","TASK_RUN_PROTOCOL_BINDING");for(String f:List.of("tenant_id","project_id","run_id","task_id","principal_id","initiator_id","command_id","launch_id","reference_sha256","operational_revision","operational_sha256"))n.set(f,intent.required(f));return n.put("launch_intent_sha256",schema.hash(intent)).put("deployment_canonical",deployment.canonical()).put("deployment_sha256",deployment.canonicalSha256());}
    private JsonNode acceptance(Bound b,TaskRunWorkflowLedger.Receipt receipt)throws Exception{return acceptance(b.value,receipt.content(),receipt.sha256());}
    private JsonNode acceptance(JsonNode binding,JsonNode receipt,String digest){var n=json.object().put("schema_version","2.0.0").put("kind","TASK_RUN_PROTOCOL_ACCEPTED").put("temporal_run_id",receipt.required("temporal_run_id").asText()).put("workflow_acceptance_sha256",digest);n.set("binding",binding.deepCopy());n.set("workflow_acceptance",receipt.deepCopy());return n;}
    private Map<String,Object> run(EnterpriseAccess.Admission a,String run){return runOriginal(a,run,a.actorId());}
    private Map<String,Object> runOriginal(EnterpriseAccess.Admission a,String run,String originalActor){if(!TransactionSynchronizationManager.isActualTransactionActive())bad();var scope=TenantScope.requireCurrent();same(scope.tenantId(),a.context().tenant_id());same(scope.subjectId(),a.actorId());return one(db.queryForList("SELECT * FROM task_run WHERE tenant_id=? AND run_id=? AND created_by=? AND execution_kind='TASK' LIMIT 2 FOR UPDATE",a.context().tenant_id(),run,originalActor));}
    private static String id(String launch,boolean accepted){return derived(launch,accepted?ACCEPT:BIND);}private static String key(String run,boolean accepted){return (accepted?"task-protocol-accepted-v2:":"task-protocol-v2:")+run;}
    private static String manifest(){try(var in=TaskRunWorkflowProtocolBinding.class.getResourceAsStream("/task-run-protocol-v2.schema.json")){if(in==null)throw new IllegalStateException("PROTOCOL_V2_CONTRACT_REQUIRED");return org.apache.commons.codec.digest.DigestUtils.sha256Hex(in);}catch(java.io.IOException e){throw new IllegalStateException(e);}}
    static final class Bound{private final TaskRunWorkflowLedger.Intent intent;private final JsonNode value;private final WaitingWorkflowDeploymentV2 deployment;private final com.ruoyi.medical.workflow.CandidateAssemblyWorkflowExtensionV1 assembly;com.ruoyi.medical.workflow.CandidateAssemblyWorkflowExtensionV1 assembly(){return assembly;}private final com.ruoyi.medical.workflow.SourceVerifierWorkflowExtensionV1 verifier;com.ruoyi.medical.workflow.SourceVerifierWorkflowExtensionV1 verifier(){return verifier;}private final com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 extension;com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 extension(){return extension;}private Bound(TaskRunWorkflowLedger.Intent intent,JsonNode value,WaitingWorkflowDeploymentV2 deployment){this(intent,value,deployment,null,null,null);}private Bound(TaskRunWorkflowLedger.Intent intent,JsonNode value,WaitingWorkflowDeploymentV2 deployment,com.ruoyi.medical.workflow.SectionWriterWorkflowExtensionV1 extension,com.ruoyi.medical.workflow.SourceVerifierWorkflowExtensionV1 verifier,com.ruoyi.medical.workflow.CandidateAssemblyWorkflowExtensionV1 assembly){this.assembly=assembly;this.verifier=verifier;this.intent=intent;this.value=value.deepCopy();this.deployment=deployment;this.extension=extension;}TaskRunWorkflowLedger.Intent intent(){return intent;}WaitingWorkflowDeploymentV2 deployment(){return deployment;}}
    static final class StartPermit{private final TaskRunWorkflowLedger.StartPermit original;private final Bound binding;private StartPermit(TaskRunWorkflowLedger.StartPermit original,Bound binding){this.original=original;this.binding=binding;}TaskRunWorkflowLedger.StartPermit original(){return original;}Bound binding(){return binding;}}
    static final class RecoveryPermit{private final TaskRunWorkflowLedger.RecoveryPermit original;private final Bound binding;private RecoveryPermit(TaskRunWorkflowLedger.RecoveryPermit original,Bound binding){this.original=original;this.binding=binding;}TaskRunWorkflowLedger.RecoveryPermit original(){return original;}Bound binding(){return binding;}}
    final class Accepted{private final TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion question;private final TaskCandidateAssemblyHumanReadAuthority.Verified human;private final EnterpriseAccess.Admission admission;private final String run;private final JsonNode value;private final Thread thread=Thread.currentThread();private final TenantScope scope=TenantScope.requireCurrent();private final Map<Object,Object> resources=Map.copyOf(TransactionSynchronizationManager.getResourceMap());private boolean ended;
        private Accepted(EnterpriseAccess.Admission admission,String run,JsonNode value,TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion question){this(admission,run,value,question,null);}
        private Accepted(EnterpriseAccess.Admission admission,String run,JsonNode value,TaskRegisteredToolWaitingAnswerAuthority.CurrentQuestion question,TaskCandidateAssemblyHumanReadAuthority.Verified human){this.human=human;this.question=question;this.admission=admission;this.run=run;this.value=value.deepCopy();if(resources.isEmpty()||!TransactionSynchronizationManager.isSynchronizationActive())bad();TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCompletion(int status){ended=true;}});}
        void requireUnchanged()throws Exception{if(question!=null)question.requireUnchanged();if(human!=null)human.require(admission);var current=TransactionSynchronizationManager.getResourceMap();if(ended||thread!=Thread.currentThread()||scope!=TenantScope.requireCurrent()||!TransactionSynchronizationManager.isActualTransactionActive()||resources.size()!=current.size()||resources.entrySet().stream().anyMatch(e->current.get(e.getKey())!=e.getValue()))bad();same(json.canonical(value),json.canonical(accepted(admission,run,human!=null?human.originalActorId():question==null?admission.actorId():question.originalActorId())));}
        String protocolSha256(){return value.required("binding").required("deployment_sha256").asText();}String originalStartCommandId(){return value.required("binding").required("command_id").asText();}String temporalRunId(){return value.required("temporal_run_id").asText();}
    }
}
